       "type": "code",
       "language": "csharp",
       "dir": "ltr",
       "code": "public static void LevelsOrder(BinNode<int> bt)\n{\n    Queue<BinNode<int>> q = new Queue<BinNode<int>>();\n    q.Insert(bt);\n    BinNode<int> btTemp;\n    while (!q.IsEmpty())\n    {\n        btTemp = q.Remove();\n        Console.Write(btTemp.GetValue() + \" \");\n        if (btTemp.HasLeft())\n            q.Insert(btTemp.GetLeft());\n        if (btTemp.HasRight())\n            q.Insert(btTemp.GetRight());\n    }\n    Console.WriteLine();\n}",
       "origin": "book"
