       "code": "public static int SumLevel(BinNode<int> bt, int k)\n{\n    if (bt == null)\n        return 0;\n    if (k == 0)\n        return bt.GetValue();\n    return SumLevel(bt.GetLeft(), k - 1) + SumLevel(bt.GetRight(), k - 1);\n}",
