       "code": "public static int CountGreater(BinNode<int> bt, int x)\n{\n    if (bt == null)\n        return 0;\n    int count = CountGreater(bt.GetLeft(), x) + CountGreater(bt.GetRight(), x);\n    if (bt.GetValue() > x)\n        count++;\n    return count;\n}",
